{
 "contract_type": "msa",
 "fields": {
  "parties": {
   "value": ["Northwind Labs, Inc.", "Copperline Software GmbH"],
   "quote": "It is made between Northwind Labs, Inc., a Delaware corporation (\"Northwind\"), and Copperline Software GmbH (\"Copperline\")."
  },
  "counterparty": {
   "value": "Copperline Software GmbH",
   "quote": "and Copperline Software GmbH (\"Copperline\")"
  },
  "effective_date": {
   "value": "2026-02-14",
   "quote": "This Master Services Agreement (the \"Agreement\") is made on 14 February 2026 (the \"Effective Date\")."
  },
  "term_months": {
   "value": 36,
   "quote": "It runs for an initial term of three (3) years."
  },
  "auto_renewal": {
   "value": true,
   "quote": "It renews automatically for further terms of twelve months each."
  },
  "renewal_notice_days": {
   "value": 30,
   "quote": "The notice must be sent no later than thirty (30) days before the renewal date."
  },
  "governing_law": {
   "value": "California",
   "quote": "The laws of the State of California govern this Agreement."
  },
  "liability_cap": {
   "value": "unlimited",
   "quote": "Each party's aggregate liability is unlimited in amount."
  },
  "payment_terms_days": {
   "value": 30,
   "quote": "Invoices are payable on Net 30 terms."
  },
  "contract_value": {
   "value": null,
   "quote": null
  },
  "termination_for_convenience": {
   "value": true,
   "quote": "Either party may end this Agreement for convenience."
  },
  "confidentiality_years": {
   "value": null,
   "quote": null
  }
 },
 "signers": [
  {
   "name": "Tobias Brandt",
   "email": "tobias.brandt@copperline.example",
   "title": "Geschäftsführer",
   "party": "Copperline Software GmbH"
  },
  {
   "name": "Dana Whitfield",
   "email": "dana@northwind.example",
   "title": "Chief Executive Officer",
   "party": "Northwind Labs, Inc."
  }
 ],
 "risks": [
  {
   "id": "unlimited_liability",
   "severity": "high",
   "message": "Liability is uncapped for both parties, so Northwind Labs, Inc. has unlimited exposure to Copperline (and can also claim without a cap).",
   "quote": "Neither party's liability under this Agreement is capped."
  },
  {
   "id": "evergreen_auto_renewal",
   "severity": "medium",
   "message": "After the 3-year initial term the Agreement renews automatically every 12 months unless notice is sent at least 30 days before the renewal date, so a missed deadline locks Northwind in.",
   "quote": "After the initial term, the Agreement is evergreen. It renews automatically for further terms of twelve months each."
  },
  {
   "id": "no_confidentiality_clause",
   "severity": "medium",
   "message": "The Agreement has no confidentiality obligations, so Northwind's confidential information shared with Copperline is not contractually protected.",
   "quote": "Apart from these promises, neither party gives any other warranty."
  },
  {
   "id": "fees_not_fixed_in_msa",
   "severity": "low",
   "message": "Fees are not stated in the MSA and depend on each Statement of Work, so there is no overall spend cap or value here.",
   "quote": "The fees for the Services are set out in each Statement of Work."
  },
  {
   "id": "cross_border_california_law",
   "severity": "low",
   "message": "California law governs although the counterparty is a German GmbH, and there is no forum or venue clause. Disputes only require executive talks first, which may complicate enforcement against Copperline.",
   "quote": "If the dispute is not settled within twenty Business Days, either party may pursue the remedies available to it."
  }
 ],
 "injection_attempt": false,
 "summary": "This is a Master Services Agreement between Northwind Labs, Inc. and Copperline Software GmbH, effective 14 February 2026, with a 3-year initial term that auto-renews yearly unless notice is given 30 days ahead. Liability is uncapped, either party can terminate for convenience on 30 days' notice, invoices are Net 30, California law applies, and fees and confidentiality terms are not set out in the document."
}
